    receive() external payable {}

    function run(address firstOwner, address secondOwner) public {
        require(true);

        c.setOwner(firstOwner); if (__ESBMC_reverted()) return;
        bool firstReverted;
        c.setOwner(secondOwner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        address ownerAfterSecond = c.owner(); if (__ESBMC_reverted()) return;

        bool thirdReverted;
        c.setOwner(secondOwner); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            thirdReverted = true;
        } else {
            thirdReverted = false;
        }

        assert(!firstReverted || thirdReverted || c.owner() == ownerAfterSecond);
    }
