import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address firstOwner, address secondOwner) internal {
        vm.assume(true);
        try c.setOwner(firstOwner) {} catch { return; }
        bool firstReverted;
        try c.setOwner(secondOwner) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        address ownerAfterSecond;
        try c.owner() returns (address __r) { ownerAfterSecond = __r; } catch { return; }
        bool thirdReverted;
        try c.setOwner(secondOwner) {
            thirdReverted = false;
        } catch {
            thirdReverted = true;
        }
        assertTrue(!firstReverted || thirdReverted || c.owner() == ownerAfterSecond);
    }

    function testFuzz_run(address firstOwner, address secondOwner) public {
        vm.assume(firstOwner.code.length == 0 && uint160(firstOwner) > 0xffff && firstOwner != address(this) && firstOwner != address(c) && firstOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && firstOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && firstOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && firstOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
